<?php
/**
 * Nahian POS Staff Member Delete Handler
 *
 * @package NRTOK_POS
 * @since   1.0.0
 */

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

if ( isset( $_GET['del_staff'] ) ) {
	if ( ! current_user_can( 'manage_options' ) ) {
		wp_die( esc_html__( 'You do not have sufficient permissions to perform this action.', 'nahian-restaurant-ordering-system' ) );
	}

	$staff_id = absint( $_GET['del_staff'] );
	if ( $staff_id > 0 ) {
		// Verify CSRF nonce generated by wp_nonce_url() in staff-list.php & staff-view.php.
		check_admin_referer( 'nrtok_delete_staff_' . $staff_id );

		global $wpdb;
		$t_staff   = $wpdb->prefix . 'nrtok_staff';
		$svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

		// phpcs:ignore WordPress.DB.DirectDatabaseQuery.DirectQuery, WordPress.DB.DirectDatabaseQuery.NoCaching
		$deleted = $wpdb->delete(
			$t_staff,
			array( 'id' => $staff_id ),
			array( '%d' )
		);

		if ( false !== $deleted && $deleted > 0 ) {
			echo '<div class="nrtok-alert nrtok-stf-alert-flex">' . $svg_check . '<span>' . sprintf( // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
				/* translators: %d: staff ID */
				esc_html__( 'Staff member #%d removed successfully!', 'nahian-restaurant-ordering-system' ),
				absint( $staff_id )
			) . '</span></div>';
		} else {
			echo '<div class="nrtok-alert" style="background:#fef2f2; border-color:#fecaca; color:#b91c1c;">' . esc_html__( 'Staff member could not be removed or was already deleted.', 'nahian-restaurant-ordering-system' ) . '</div>';
		}
	}
}